/* Übersetzung eines Wortes holen. Ohne Treffer: leer. */
window.wortUebersetzung = function (de, sprache) {
  var e = window.WORT_SPRACHEN[de];
  if (!e || !sprache) return null;
  return e[sprache] || null;
};
